-- Everything needed to decide whether a message should be sent, and to record what happened when
-- it was. The content itself is not here: a template and a rendered body are documents and live in
-- MongoDB, so the rows the dispatcher claims stay narrow and the partial index below stays small.
--
-- Identifiers are UUIDs generated by the database; gen_random_uuid() is built in from PostgreSQL 13
-- onwards, so no extension is needed.
--
-- Every table here carries the same five columns as com.confluo.common.jpa.entity.BaseJpaEntity:
-- the id, the two timestamps Hibernate maintains, and the two soft-state markers. That includes
-- delivery_attempts, which uses only three of them - see the note above that table. The outbox and
-- the consumed-message ledger that common-amqp adds to this database are the exception, and they
-- are not JPA entities at all: they are reached through JdbcTemplate.
--
-- Versions 1-999 belong to this service; 1000-1099 are common-amqp's, which ships the outbox and
-- the consumed-message ledger into the same database.

-- Who can be reached, and how. The firebase uid is the identity every other service already speaks
-- in, so nothing here needs a second notion of a user.
--
-- The contact details are a copy, kept current by consuming the events of whichever service owns
-- users. That is the point: a send must not depend on that service being up, and contacts carried
-- in every event contract would go stale sitting in an outbox. `source` says which of the ways a
-- row was written, because a row that is wrong is only answerable with its provenance.
CREATE TABLE recipients (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    firebase_uid        VARCHAR(128)    NOT NULL,
    email               VARCHAR(320),
    email_verified      BOOLEAN         NOT NULL DEFAULT FALSE,
    phone_e164          VARCHAR(20),
    phone_verified      BOOLEAN         NOT NULL DEFAULT FALSE,
    -- The platform's language code, with no foreign key: that table is in another database. A code
    -- the platform has since disabled is cleared by the handler for that event, not by a constraint.
    language_code       VARCHAR(8),
    -- IANA, e.g. Europe/Bucharest. Nothing reads it yet; it is here so that holding a message until
    -- someone's morning is a change to a service rather than a migration.
    timezone            VARCHAR(64),
    source              VARCHAR(32)     NOT NULL,
    last_synced_at      TIMESTAMPTZ     NOT NULL,
    CONSTRAINT uq_recipients_firebase_uid UNIQUE (firebase_uid),
    -- A recipient reachable by nothing is a mistake upstream, and failing at the insert says so
    -- where it happened rather than at the first send that finds no destination.
    CONSTRAINT ck_recipients_reachable CHECK (email IS NOT NULL OR phone_e164 IS NOT NULL),
    -- E.164 exactly: a plus, a non-zero country digit, then up to fourteen more. The column is
    -- documented as normalised, and this is what makes that true rather than hoped for - every
    -- provider wants this form, and a number stored as somebody typed it fails at the provider,
    -- which is the most expensive place to find out.
    CONSTRAINT ck_recipients_phone_e164 CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{1,14}$'),
    -- Lowercase, so that ix_recipients_email can actually be used to answer "whose address is
    -- this?" when a provider's callback names one. An upper(email) = upper(?) comparison would
    -- read better in a repository and scan the table on a path that runs per bounce. The local
    -- part of an address is case-sensitive by the RFC and treated otherwise by every provider that
    -- exists, and the alternative is worse: a bounce for John@x.com failing to suppress john@x.com.
    CONSTRAINT ck_recipients_email_lowercase CHECK (email IS NULL OR email = lower(email)),
    CONSTRAINT ck_recipients_source
        CHECK (source IN ('IDENTITY_EVENT', 'FIREBASE_BACKFILL', 'SEND_REQUEST', 'ADMIN'))
);

-- What someone has agreed to receive, per channel and per category. One row per combination; the
-- absence of a row means the default, which the service decides - on for transactional and account
-- messages, off for marketing, because opt-in is both the lawful default here and the one that
-- fails safe.
CREATE TABLE notification_preferences (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    recipient_id        UUID            NOT NULL,
    channel             VARCHAR(16)     NOT NULL,
    category            VARCHAR(16)     NOT NULL,
    enabled             BOOLEAN         NOT NULL,
    -- Covers every row, soft-deleted ones included. That is intended: a preference is updated in
    -- place rather than replaced, so a second row for the same combination is a bug either way.
    CONSTRAINT uq_notification_preferences_scope UNIQUE (recipient_id, channel, category),
    CONSTRAINT fk_notification_preferences_recipient
        FOREIGN KEY (recipient_id) REFERENCES recipients (id),
    CONSTRAINT ck_notification_preferences_channel
        CHECK (channel IN ('EMAIL', 'SMS', 'IN_APP', 'PUSH')),
    CONSTRAINT ck_notification_preferences_category
        CHECK (category IN ('TRANSACTIONAL', 'ACCOUNT', 'MARKETING')),
    -- The rule that a password reset cannot be switched off, written where it cannot be bypassed.
    -- A service enforcing this alone would be one refactor away from a silent hole, and the hole
    -- would be invisible: nobody complains about the message they did not get.
    CONSTRAINT ck_notification_preferences_transactional
        CHECK (category <> 'TRANSACTIONAL' OR enabled)
);

-- Destinations nothing may be sent to again. Keyed by the destination itself rather than by a
-- recipient, and deliberately: an address that hard-bounced or a number that answered STOP has to
-- stay suppressed even when it is later attached to a different uid. Keying it to a person would
-- let a re-registration quietly reopen it.
CREATE TABLE suppressions (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    channel             VARCHAR(16)     NOT NULL,
    destination         VARCHAR(320)    NOT NULL,
    reason              VARCHAR(16)     NOT NULL,
    -- When it became true, which is not when the row was written: a bounce notification can arrive
    -- hours after the bounce, and a STOP is timestamped by the provider that received it.
    suppressed_at       TIMESTAMPTZ     NOT NULL,
    notes               TEXT,
    CONSTRAINT uq_suppressions_destination UNIQUE (channel, destination),
    -- The unique constraint above is exact, so the stored form has to be settled here or two rows
    -- differing only in case would both be allowed and only one of them ever found - which, for a
    -- suppression list, means sending to an address somebody already told us not to.
    CONSTRAINT ck_suppressions_destination_lowercase CHECK (destination = lower(destination)),
    CONSTRAINT ck_suppressions_channel CHECK (channel IN ('EMAIL', 'SMS', 'IN_APP', 'PUSH')),
    CONSTRAINT ck_suppressions_reason
        CHECK (reason IN ('HARD_BOUNCE', 'COMPLAINT', 'UNSUBSCRIBED', 'STOP', 'INVALID', 'MANUAL'))
);

-- One row per message that should exist, and the state machine for it. Written by the pipeline
-- inside the transaction that decided to send, and claimed afterwards by the dispatcher - the same
-- shape as the outbox, and for the same reason: nothing reaches a provider before the decision to
-- send it has committed.
CREATE TABLE notifications (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    -- Null for an ad-hoc send that names a raw destination and no person.
    recipient_id        UUID,
    channel             VARCHAR(16)     NOT NULL,
    category            VARCHAR(16)     NOT NULL,
    template_key        VARCHAR(128)    NOT NULL,
    -- The locale actually rendered, after the fallback chain ran - not the one that was asked for.
    locale              VARCHAR(16)     NOT NULL,
    -- Frozen when the message was rendered. If someone changes their email afterwards, this row
    -- still says where this message went, which is the only answer worth having about a message
    -- already sent.
    destination         VARCHAR(320)    NOT NULL,
    status              VARCHAR(16)     NOT NULL,
    attempts            INTEGER         NOT NULL DEFAULT 0,
    next_attempt_at     TIMESTAMPTZ     NOT NULL,
    -- Honoured by next_attempt_at when set. Nothing sets it yet; quiet hours would.
    scheduled_for       TIMESTAMPTZ,
    last_error          TEXT,
    -- What must not be sent twice, ever - not a time window. 'welcome:<uid>' sent once is the
    -- shape; a caller that wants a repeatable send passes null. Redis checks a short window in
    -- front of this, which is an optimisation: the unique index below is what actually decides.
    dedup_key           VARCHAR(255),
    correlation_id      VARCHAR(128),
    -- The envelope's eventId, when an event asked for this. It is what traces a message back to
    -- the thing that happened.
    trigger_event_id    UUID,
    requested_by        VARCHAR(128),
    CONSTRAINT fk_notifications_recipient FOREIGN KEY (recipient_id) REFERENCES recipients (id),
    CONSTRAINT ck_notifications_channel CHECK (channel IN ('EMAIL', 'SMS', 'IN_APP', 'PUSH')),
    CONSTRAINT ck_notifications_category
        CHECK (category IN ('TRANSACTIONAL', 'ACCOUNT', 'MARKETING')),
    CONSTRAINT ck_notifications_status
        CHECK (status IN ('PENDING', 'SENDING', 'SENT', 'DELIVERED', 'FAILED', 'SUPPRESSED', 'CANCELLED')),
    CONSTRAINT ck_notifications_attempts CHECK (attempts >= 0)
);

-- One row per call actually made to a provider.
--
-- created_at IS the moment the provider was called, because the row is written immediately before
-- the call - which is why there is no started_at beside it: one fact in two columns is how the two
-- come to disagree. updated_at is the moment the outcome last changed, and so the only record of
-- when a status callback arrived, hours after the send in the ordinary case. disabled_at and
-- deleted_at are unused here - an attempt is a fact, and neither disabling nor soft-deleting a
-- provider call that happened means anything - but they come with the shape every other table in
-- this schema has, and deleted_at is where a retention policy would hide old rows before purging.
CREATE TABLE delivery_attempts (
    id                  UUID            PRIMARY KEY,
    created_at          TIMESTAMPTZ     NOT NULL,
    updated_at          TIMESTAMPTZ     NOT NULL,
    disabled_at         TIMESTAMPTZ,
    deleted_at          TIMESTAMPTZ,
    notification_id     UUID            NOT NULL,
    attempt_no          INTEGER         NOT NULL,
    -- Deliberately not constrained to a list. Which providers exist is operational, and adding one
    -- should be an adapter and a setting rather than a migration - the whole reason sending sits
    -- behind an interface. GMAIL_SMTP and TWILIO are what write it today.
    provider            VARCHAR(32)     NOT NULL,
    -- What the provider called it, and how a status callback finds its way back to this row.
    provider_message_id VARCHAR(255),
    status              VARCHAR(16)     NOT NULL,
    error_code          VARCHAR(64),
    error_message       TEXT,
    -- Null while the call is in flight, which is also how a process that died mid-send is spotted.
    -- With created_at, these two are how long the provider took.
    finished_at         TIMESTAMPTZ,
    CONSTRAINT fk_delivery_attempts_notification
        FOREIGN KEY (notification_id) REFERENCES notifications (id),
    CONSTRAINT uq_delivery_attempts_sequence UNIQUE (notification_id, attempt_no),
    CONSTRAINT ck_delivery_attempts_attempt_no CHECK (attempt_no >= 1),
    CONSTRAINT ck_delivery_attempts_status
        CHECK (status IN ('ACCEPTED', 'REJECTED', 'DELIVERED', 'BOUNCED', 'UNDELIVERED', 'FAILED'))
);

-- What the dispatcher reads, constantly, and nothing else does. Partial for the reason the outbox's
-- own index is: sent rows are the overwhelming majority and keeping them out of the index is what
-- stops it growing with the table.
CREATE INDEX ix_notifications_due ON notifications (next_attempt_at) WHERE status = 'PENDING';

-- The real deduplication. Partial because most rows carry no key, and unique because "once, ever"
-- has to be decided by something that cannot be raced.
CREATE UNIQUE INDEX uq_notifications_dedup_key ON notifications (dedup_key) WHERE dedup_key IS NOT NULL;

-- "What have we sent this person", which is the delivery log's only expensive query.
CREATE INDEX ix_notifications_recipient ON notifications (recipient_id, created_at DESC);

-- How a provider's status callback finds the attempt it is about. Unique per provider: two
-- providers may well hand out the same opaque string, and only together do they identify a call.
CREATE UNIQUE INDEX uq_delivery_attempts_provider_message_id
    ON delivery_attempts (provider, provider_message_id) WHERE provider_message_id IS NOT NULL;

CREATE INDEX ix_delivery_attempts_notification ON delivery_attempts (notification_id);

-- Looking a person up by the address an event or a webhook mentions, rather than by their uid.
CREATE INDEX ix_recipients_email ON recipients (email) WHERE email IS NOT NULL;
CREATE INDEX ix_recipients_phone_e164 ON recipients (phone_e164) WHERE phone_e164 IS NOT NULL;

-- The listings filter on these, and every resource row carries one.
CREATE INDEX ix_recipients_deleted_at ON recipients (deleted_at);
CREATE INDEX ix_notification_preferences_deleted_at ON notification_preferences (deleted_at);
CREATE INDEX ix_suppressions_deleted_at ON suppressions (deleted_at);
CREATE INDEX ix_notifications_deleted_at ON notifications (deleted_at);
